WITH by_dimension AS (SELECT d.country, e.status, COUNT(*) AS num_rows, ROUND(AVG(e.balance), 2) AS avg_balance, GROUPING_ID() AS level_id FROM accounts e LEFT JOIN customers d ON e.customer_id = d.id GROUP BY GROUPING SETS ((d.country, e.status), (d.country), ())) SELECT status, num_rows, level_id, CASE WHEN status RLIKE '^(FROZEN|CLOSED)$' THEN 'GROUP_A' WHEN status RLIKE '^(OPEN)$' THEN 'OTHER_ZONE' ELSE 'PRIORITY' END AS status_zone FROM by_dimension ORDER BY status ASC NULLS FIRST;
